const data = require('fs').readFileSync(0, 'utf8');
const tokens = data.split(/\s+/).filter(s => s.length > 0);
let ptr = 0;

const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;

const dx = [0, 0, -1, 1, -1, 1, -1, 1];
const dy = [1, -1, 0, 0, 1, 1, -1, -1];

const MAX = 5 * 30 + 5;
const DIM = 2 * MAX;

const marked = new Uint8Array(DIM * DIM * 8 * 32 * 6);

function idx(x, y, dir, lev, far) {
  return ((((x * DIM + y) * 8 + dir) * 32 + lev) * 6 + far);
}

const mp = new Set();
const t = new Array(100).fill(0);

function rot(dir) {
  if (dir === UP) return [UPLEFT, UPRIGHT];
  if (dir === DOWN) return [DOWNLEFT, DOWNRIGHT];
  if (dir === LEFT) return [UPLEFT, DOWNLEFT];
  if (dir === RIGHT) return [UPRIGHT, DOWNRIGHT];
  if (dir === UPLEFT) return [UP, LEFT];
  if (dir === UPRIGHT) return [UP, RIGHT];
  if (dir === DOWNLEFT) return [DOWN, LEFT];
  if (dir === DOWNRIGHT) return [DOWN, RIGHT];
}

function node(_x, _y, _dir, _lev, _far) {
  return { x: _x, y: _y, dir: _dir, lev: _lev, far: _far };
}

const Q = [];
let head = 0;

function main() {
  const n = parseInt(tokens[ptr++], 10);
  for (let i = 1; i <= n; i++)
    t[i] = parseInt(tokens[ptr++], 10);

  let ans = 0;
  Q.push(node(MAX, MAX, UP, 1, 1));

  marked[idx(MAX, MAX, UP, 1, 1)] = 1;
  mp.add(MAX * 1000 + MAX);
