    const v = Q[head++];

    const key = v.x * 1000 + v.y;
    if (!mp.has(key)) {
      mp.add(key);
      ans++;
    }

    const lev = v.lev;
    const far = v.far;

    let x2 = v.x, y2 = v.y;

    if (lev === n + 1)
      continue;

    if (far !== t[lev]) {
      x2 += dx[v.dir];
      y2 += dy[v.dir];
      const id = idx(x2, y2, v.dir, lev, far + 1);
      if (marked[id]) continue;
      marked[id] = 1;
      Q.push(node(x2, y2, v.dir, lev, far + 1));
    } else {
      const dirs = rot(v.dir);
      const id1 = idx(v.x, v.y, dirs[0], lev + 1, 0);
      if (!marked[id1]) {
        marked[id1] = 1;
        Q.push(node(v.x, v.y, dirs[0], lev + 1, 0));
      }
      const id2 = idx(v.x, v.y, dirs[1], lev + 1, 0);
      if (!marked[id2]) {
        marked[id2] = 1;
        Q.push(node(v.x, v.y, dirs[1], lev + 1, 0));
      }
    }
  }
  console.log(ans);
}

main();
